exercises.solutionCode:
#include <stddef.h>
typedef struct {
    unsigned int freq_hz;
    unsigned int duty_permille;
    unsigned int high_us;
} PwmProfile;

int pwm_profile(unsigned int timer_clk_hz, unsigned int psc, unsigned int arr,
                unsigned int ccr, PwmProfile *out)
{
    if (out == NULL || timer_clk_hz == 0u) {
        return -1;
    }

    /* psc + 1 用 64 位提升，避免 psc 取到边界值时 32 位回绕 */
    unsigned long long counter_clk =
        (unsigned long long)timer_clk_hz / ((unsigned long long)psc + 1ULL);
    if (counter_clk == 0ULL) {
        return -1;              /* 分频后计数时钟为 0，参数无意义 */
    }

    unsigned long long period = (unsigned long long)arr + 1ULL;  /* 一个周期的计数次数 */
    if ((unsigned long long)ccr > period) {
        return -1;              /* PWM1 模式下 ccr 合法范围是 0 ~ arr + 1 */
    }

    out->freq_hz = (unsigned int)(counter_clk / period);
    out->duty_permille = (unsigned int)((unsigned long long)ccr * 1000ULL / period);
    out->high_us = (unsigned int)((unsigned long long)ccr * 1000000ULL / counter_clk);
    return 0;
}
